import { useCallback, useRef, useState } from 'react';
import type { protectionNavigationPolicy } from './session-transitions';
import { useRecoveryBackup } from './use-recovery-backup';

/** Whether any secret typed into setup, or generated by it, is still held. */
export function holdsSetupSecret(values: {
  invite: string;
  passphrase: string;
  confirmation: string;
  recoveryPhrase: string;
  pairingPhrase: string;
  generatedRecoveryPhrase: string | null;
}): boolean {
  return Boolean(
    values.invite ||
    values.passphrase ||
    values.confirmation ||
    values.recoveryPhrase ||
    values.pairingPhrase ||
    values.generatedRecoveryPhrase,
  );
}

/**
 * Owns every secret setup holds: the invite code, the passphrase and its
 * confirmation, a typed recovery phrase, a CLI pairing phrase and the
 * generated recovery phrase. None of them is persisted in the checkpoint, and
 * `clear` is the one place they are dropped together.
 */
export function useSetupSecrets() {
  const [invite, setInvite] = useState('');
  const [passphrase, setPassphrase] = useState('');
  const [confirmation, setConfirmation] = useState('');
  const [recoveryPhrase, setRecoveryPhrase] = useState('');
  const [pairingPhrase, setPairingPhrase] = useState('');
  const backup = useRecoveryBackup();
  const { clearBackup, navigateBackup } = backup;

  /**
   * Whether a secret is held when the navigation guard is evaluated. `clear`
   * updates this value before sidebar navigation, so the verdict reflects the
   * cleared state without waiting for another render.
   */
  const held = useRef(false);
  held.current = holdsSetupSecret({
    invite,
    passphrase,
    confirmation,
    recoveryPhrase,
    pairingPhrase,
    generatedRecoveryPhrase: backup.generatedRecoveryPhrase,
  });

  const clear = useCallback((): void => {
    clearBackup();
    setInvite('');
    setPassphrase('');
    setConfirmation('');
    setRecoveryPhrase('');
    setPairingPhrase('');
    held.current = false;
  }, [clearBackup]);

  /**
   * Drops what a move to another step leaves behind. Typed phrases and the
   * invite belong to the step they were typed on; the passphrase and the
   * generated phrase follow the protection policy.
   */
  const navigate = useCallback(
    (policy: ReturnType<typeof protectionNavigationPolicy>): void => {
      navigateBackup(policy);
      setRecoveryPhrase('');
      setPairingPhrase('');
      setInvite('');
      if (policy.clearPassphrase) {
        setPassphrase('');
        setConfirmation('');
      }
    },
    [navigateBackup],
  );

  return {
    invite,
    setInvite,
    passphrase,
    setPassphrase,
    confirmation,
    setConfirmation,
    recoveryPhrase,
    setRecoveryPhrase,
    pairingPhrase,
    setPairingPhrase,
    backup,
    held,
    clear,
    navigate,
  };
}

export type SetupSecrets = ReturnType<typeof useSetupSecrets>;
